1	{
2	  "name": "cartwell",
3	  "version": "0.1.0",
4	  "private": true,
5	  "type": "module",
6	  "scripts": {
7	    "start": "node server.ts serve",
8	    "help": "node server.ts --help",
9	    "test": "node --test server.test.ts"
10	  }
11	}
12

1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	
7	const PRODUCT: string = 'Cartwell';
8	const RESOURCE: string = 'products';
9	const MAX_BODY_BYTES: number = 1_048_576;
10	
11	// ---------- 数据模型 ----------
12	
13	interface Attribute {
14	  name: string;
15	  value: string;
16	}
17	interface Spec {
18	  attributes: Attribute[];
19	  price: string;
20	  stock: number;
21	}
22	interface Product {
23	  id: string;
24	  name: string;
25	  specs: Spec[];
26	  createdAt: string;
27	}
28	type FieldName = 'name' | 'spec' | 'attributes' | 'attrName' | 'attrValue' | 'price' | 'stock';
29	interface FieldError {
30	  path: string;
31	  field: FieldName;
32	  message: string;
33	  specIndex?: number;
34	  attributeIndex?: number;
35	}
36	type ValidationResult =
37	  | { ok: true; name: string; specs: Spec[] }
38	  | { ok: false; errors: FieldError[] };
39	
40	const PRICE_PATTERN = /^\d+(?:\.\d{1,2})?$/;
41	
42	function isPlainObject(value: unknown): value is Record<string, unknown> {
43	  return typeof value === 'object' && value !== null && !Array.isArray(value);
44	}
45	
46	// 金额字符串规范化：只接受零或最多两位小数的十进制写法，按字符串运算避免精度丢失。
47	function normalizePrice(raw: unknown): { ok: true; price: string } | { ok: false } {
48	  if (typeof raw !== 'string' || !PRICE_PATTERN.test(raw)) return { ok: false };
49	  const [wholeRaw, fractionRaw] = raw.split('.');
50	  const whole = wholeRaw.replace(/^0+(?=\d)/, '');
51	  const fraction = (fractionRaw ?? '').padEnd(2, '0');
52	  return { ok: true, price: `${whole}.${fraction}` };
53	}
54	
55	function validateStock(raw: unknown): number | undefined {
56	  if (typeof raw !== 'number' || !Number.isInteger(raw)) return undefined;
57	  if (raw < 0 || !Number.isSafeInteger(raw)) return undefined;
58	  return raw;
59	}
60	
61	// 规格的顺序无关签名：属性编码为 JSON 后排序连接，无碰撞风险；大小写敏感。
62	function specSignature(attributes: Attribute[]): string {
63	  return attributes
64	    .map((attribute) => JSON.stringify([attribute.name, attribute.value]))
65	    .sort()
66	    .join('\u0000');
67	}
68	
69	// 按与网页表单一致的规则校验并规范化整个商品，返回所有需要修正的字段。
70	function validateProduct(input: unknown): ValidationResult {
71	  const errors: FieldError[] = [];
72	
73	  if (!isPlainObject(input)) {
74	    return { ok: false, errors: [{ path: '', field: 'spec', message: '请求体必须是一个商品对象' }] };
75	  }
76	
77	  let name = '';
78	  if (typeof input.name !== 'string') {
79	    errors.push({ path: 'name', field: 'name', message: '商品名称必须是文字' });
80	  } else {
81	    name = input.name.trim();
82	    if (name === '') errors.push({ path: 'name', field: 'name', message: '商品名称不能为空' });
83	  }
84	
85	  if (!Array.isArray(input.specs)) {
86	    errors.push({ path: 'specs', field: 'spec', message: '规格必须是数组，且至少包含一条规格' });
87	    return { ok: false, errors };
88	  }
89	  if (input.specs.length === 0) {
90	    errors.push({ path: 'specs', field: 'spec', message: '至少需要一条规格' });
91	    return { ok: false, errors };
92	  }
93	
94	  const normalizedSpecs: Spec[] = [];
95	  const specSignatures = new Map<string, number>();
96	  const flaggedSpecs = new Set<number>();
97	
98	  input.specs.forEach((rawSpec, specIndex) => {
99	    const basePath = `specs[${specIndex}]`;
100	    const specValid: Spec = { attributes: [], price: '', stock: 0 };
101	    let specOk = true;
102	
103	    if (!isPlainObject(rawSpec)) {
104	      errors.push({ path: basePath, field: 'spec', specIndex, message: '该规格格式不正确' });
105	      return;
106	    }
107	
108	    if (!Array.isArray(rawSpec.attributes) || rawSpec.attributes.length === 0) {
109	      errors.push({
110	        path: `${basePath}.attributes`, field: 'attributes', specIndex,
111	        message: '该规格至少需要一个属性',
112	      });
113	      specOk = false;
114	    } else {
115	      const seenNames = new Set<string>();
116	      rawSpec.attributes.forEach((rawAttribute, attributeIndex) => {
117	        const attrPath = `${basePath}.attributes[${attributeIndex}]`;
118	        if (!isPlainObject(rawAttribute)) {
119	          errors.push({
120	            path: attrPath, field: 'attrName', specIndex, attributeIndex,
121	            message: '该属性格式不正确',
122	          });
123	          specOk = false;
124	          return;
125	        }
126	        let attributeName: string;
127	        let attributeValue: string;
128	        if (typeof rawAttribute.name !== 'string') {
129	          errors.push({
130	            path: `${attrPath}.name`, field: 'attrName', specIndex, attributeIndex,
131	            message: '属性名称必须是文字',
132	          });
133	          specOk = false;
134	          return;
135	        }
136	        attributeName = rawAttribute.name.trim();
137	        if (attributeName === '') {
138	          errors.push({
139	            path: `${attrPath}.name`, field: 'attrName', specIndex, attributeIndex,
140	            message: '属性名称不能为空',
141	          });
142	          specOk = false;
143	          return;
144	        }
145	        if (typeof rawAttribute.value !== 'string') {
146	          errors.push({
147	            path: `${attrPath}.value`, field: 'attrValue', specIndex, attributeIndex,
148	            message: '属性值必须是文字',
149	          });
150	          specOk = false;
151	          return;
152	        }
153	        attributeValue = rawAttribute.value.trim();
154	        if (attributeValue === '') {
155	          errors.push({
156	            path: `${attrPath}.value`, field: 'attrValue', specIndex, attributeIndex,
157	            message: '属性值不能为空',
158	          });
159	          specOk = false;
160	          return;
161	        }
162	        if (seenNames.has(attributeName)) {
163	          errors.push({
164	            path: `${attrPath}.name`, field: 'attrName', specIndex, attributeIndex,
165	            message: `属性名称「${attributeName}」在同一规格内重复`,
166	          });
167	          specOk = false;
168	          return;
169	        }
170	        seenNames.add(attributeName);
171	        specValid.attributes.push({ name: attributeName, value: attributeValue });
172	      });
173	    }
174	
175	    const priceResult = normalizePrice(rawSpec.price);
176	    if (!priceResult.ok) {
177	      errors.push({
178	        path: `${basePath}.price`, field: 'price', specIndex,
179	        message: '售价必须是十进制金额字符串：允许零和最多两位小数，不接受负数、指数写法、千位分隔符或更多位小数',
180	      });
181	      specOk = false;
182	    } else {
183	      specValid.price = priceResult.price;
184	    }
185	
186	    const stock = validateStock(rawSpec.stock);
187	    if (stock === undefined) {
188	      errors.push({
189	        path: `${basePath}.stock`, field: 'stock', specIndex,
190	        message: '库存必须是非负安全整数，不能留空或使用小数',
191	      });
192	      specOk = false;
193	    } else {
194	      specValid.stock = stock;
195	    }
196	
197	    if (specOk) {
198	      const signature = specSignature(specValid.attributes);
199	      const firstIndex = specSignatures.get(signature);
200	      if (firstIndex === undefined) {
201	        specSignatures.set(signature, specIndex);
202	      } else {
203	        if (!flaggedSpecs.has(firstIndex)) {
204	          errors.push({
205	            path: `specs[${firstIndex}]`, field: 'spec', specIndex: firstIndex,
206	            message: `与第 ${specIndex + 1} 条规格的属性名称和值完全相同`,
207	          });
208	          flaggedSpecs.add(firstIndex);
209	        }
210	        errors.push({
211	          path: basePath, field: 'spec', specIndex,
212	          message: `与第 ${firstIndex + 1} 条规格的属性名称和值完全相同（调换属性顺序也算重复）`,
213	        });
214	        flaggedSpecs.add(specIndex);
215	      }
216	    }
217	    normalizedSpecs.push(specValid);
218	  });
219	
220	  if (errors.length > 0) return { ok: false, errors };
221	  return { ok: true, name, specs: normalizedSpecs };
222	}
223	
224	// ---------- 持久化 ----------
225	
226	const args: string[] = process.argv.slice(2);
227	const help: string = `Cartwell - 商品目录与购物订单
228	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
229	       node server.ts --help
230	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
231	Port 0 selects an available port.
232	`;
233	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
234	  process.stdout.write(help);
235	  process.exit(args.length === 0 ? 2 : 0);
236	}
237	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
238	let host: string = '127.0.0.1';
239	let port: number = 8080;
240	let dataDir: string = 'data';
241	while (args.length) {
242	  const flag = args.shift();
243	  const value = args.shift();
244	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
245	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
246	  }
247	  if (flag === '--host') host = value;
248	  else if (flag === '--port') {
249	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
250	    port = Number(value);
251	  } else dataDir = value;
252	}
253	
254	mkdirSync(dataDir, { recursive: true });
255	const dataFile = join(dataDir, 'products.json');
256	const tempFile = join(dataDir, 'products.json.tmp');
257	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
258	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
259	}
260	
261	function readProducts(): Product[] {
262	  const records: unknown = JSON.parse(readFileSync(dataFile, 'utf8'));
263	  if (!Array.isArray(records)) throw new Error('Invalid record list');
264	  return records as Product[];
265	}
266	
267	// 先写临时文件再重命名：写盘失败时旧数据保持完好，不会出现部分保存。
268	function saveProducts(products: Product[]): void {
269	  writeFileSync(tempFile, `${JSON.stringify(products, null, 2)}\n`);
270	  renameSync(tempFile, dataFile);
271	}
272	
273	// ---------- 网页 ----------
274	
275	function escapeHtml(value: string): string {
276	  return value
277	    .replace(/&/g, '&amp;')
278	    .replace(/</g, '&lt;')
279	    .replace(/>/g, '&gt;')
280	    .replace(/"/g, '&quot;')
281	    .replace(/'/g, '&#39;');
282	}
283	
284	function renderProductList(products: Product[]): string {
285	  if (products.length === 0) {
286	    return '<p id="empty-tip" class="empty">还没有商品记录。使用下方「新增商品」表单创建第一条记录。</p>';
287	  }
288	  const items = products.map((product) => {
289	    const specs = product.specs.map((spec) => {
290	      const attributes = spec.attributes
291	        .map((attribute) => `<span class="attr">${escapeHtml(attribute.name)}：${escapeHtml(attribute.value)}</span>`)
292	        .join('<span class="attr-sep">，</span>');
293	      const outOfStock = spec.stock === 0 ? '<span class="badge badge-oos">缺货</span>' : '';
294	      return `<li class="spec-row"><span class="attrs">${attributes}</span>`
295	        + `<span class="price">¥${escapeHtml(spec.price)}</span>`
296	        + `<span class="stock">库存 ${spec.stock}</span>${outOfStock}</li>`;
297	    }).join('');
298	    return `<li class="product"><h3>${escapeHtml(product.name)}</h3><ul class="specs">${specs}</ul></li>`;
299	  }).join('');
300	  return `<ul id="product-list" class="product-list">${items}</ul>`;
301	}
302	
303	const PAGE_STYLE = `
304	:root{color-scheme:light}
305	*{box-sizing:border-box}
306	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
307	a{color:#175b9c}
308	h1{margin-bottom:0}
309	h2{margin-top:2.5rem;border-bottom:1px solid #d9dee8;padding-bottom:.3rem}
310	h3{margin:.4rem 0}
311	.empty{color:#6b7280;background:#f4f6fa;border:1px dashed #c6cedb;padding:.8rem 1rem;border-radius:.5rem}
312	.product-list{list-style:none;padding:0}
313	.product{border:1px solid #d9dee8;border-radius:.6rem;padding:.6rem 1rem;margin:1rem 0;background:#fff}
314	.specs{list-style:none;padding:0;margin:.4rem 0}
315	.spec-row{display:flex;flex-wrap:wrap;gap:.4rem .8rem;align-items:center;padding:.35rem 0;border-top:1px dashed #e5e8ef;font-size:.95rem}
316	.attr{color:#374151}
317	.price{font-variant-numeric:tabular-nums;color:#0f5132;font-weight:600}
318	.stock{color:#4b5563;font-variant-numeric:tabular-nums}
319	.badge{font-size:.8rem;padding:.05rem .5rem;border-radius:999px}
320	.badge-oos{background:#fde8e8;color:#b4231a;border:1px solid #f3b6b1}
321	form#product-form{border:1px solid #d9dee8;border-radius:.6rem;padding:1rem 1.2rem;background:#fbfcfe}
322	.spec{border:1px solid #d3dae6;border-radius:.5rem;padding:.6rem .9rem;margin:.8rem 0;background:#fff}
323	.attr-row{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center;margin:.4rem 0}
324	.attr-row input{max-width:12rem}
325	input[type=text]{padding:.35rem .5rem;border:1px solid #b9c2d1;border-radius:.35rem;font:inherit}
326	input.invalid{border-color:#c02b1f;box-shadow:0 0 0 2px #f8d5d0}
327	button{font:inherit;padding:.35rem .8rem;border-radius:.35rem;border:1px solid #9aa7bb;background:#f3f6fb;cursor:pointer}
328	button.primary{background:#175b9c;color:#fff;border-color:#175b9c;font-weight:600}
329	button:disabled{opacity:.6;cursor:wait}
330	.err{color:#b4231a;font-size:.85rem;min-height:1em}
331	#form-status{margin:.8rem 0;padding:.6rem .9rem;border-radius:.5rem;display:none}
332	#form-status.error{display:block;background:#fde8e8;border:1px solid #f3b6b1;color:#8a1c14}
333	.field label{display:flex;gap:.5rem;align-items:center;flex-wrap:wrap}
334	.form-actions{margin-top:.8rem;display:flex;gap:.8rem;align-items:center}
335	`;
336	
337	const PAGE_SCRIPT = `
338	(function () {
339	  var form = document.getElementById('product-form');
340	  var nameInput = document.getElementById('product-name');
341	  var specsBox = document.getElementById('specs');
342	  var statusBox = document.getElementById('form-status');
343	  var submitBtn = document.getElementById('submit-btn');
344	
345	  function attrRowHtml() {
346	    return '<div class="attr-row">'
347	      + '<input type="text" data-attr-name placeholder="属性名称，如：颜色" maxlength="100">'
348	      + '<input type="text" data-attr-value placeholder="属性值，如：红色" maxlength="200">'
349	      + '<button type="button" class="remove-attr">删除属性</button>'
350	      + '<span class="err" data-err="attrName"></span>'
351	      + '<span class="err" data-err="attrValue"></span>'
352	      + '</div>';
353	  }
354	  function specCardHtml() {
355	    return '<fieldset class="spec" data-spec>'
356	      + '<legend data-spec-no>规格 1</legend>'
357	      + '<div class="attrs" data-attrs>' + attrRowHtml() + '</div>'
358	      + '<p><button type="button" class="add-attr">添加属性</button> '
359	      + '<button type="button" class="remove-spec">删除此规格</button></p>'
360	      + '<p class="field"><label>售价 <input type="text" inputmode="decimal" data-price placeholder="如 10.00"></label>'
361	      + '<span class="err" data-err="price"></span></p>'
362	      + '<p class="field"><label>库存 <input type="text" inputmode="numeric" data-stock placeholder="非负整数"></label>'
363	      + '<span class="err" data-err="stock"></span></p>'
364	      + '<p class="err" data-err="spec"></p>'
365	      + '<p class="err" data-err="attributes"></p>'
366	      + '</fieldset>';
367	  }
368	  function refreshNumbers() {
369	    var cards = specsBox.querySelectorAll('[data-spec]');
370	    for (var i = 0; i < cards.length; i++) {
371	      cards[i].querySelector('[data-spec-no]').textContent = '规格 ' + (i + 1);
372	    }
373	  }
374	  function addSpec() {
375	    specsBox.insertAdjacentHTML('beforeend', specCardHtml());
376	    refreshNumbers();
377	  }
378	  specsBox.addEventListener('click', function (event) {
379	    var target = event.target;
380	    if (!(target instanceof Element)) return;
381	    if (target.classList.contains('add-attr')) {
382	      var card = target.closest('[data-spec]');
383	      card.querySelector('[data-attrs]').insertAdjacentHTML('beforeend', attrRowHtml());
384	    } else if (target.classList.contains('remove-attr')) {
385	      var row = target.closest('.attr-row');
386	      if (row.parentElement.querySelectorAll('.attr-row').length > 1) row.remove();
387	    } else if (target.classList.contains('remove-spec')) {
388	      if (specsBox.querySelectorAll('[data-spec]').length > 1) {
389	        target.closest('[data-spec]').remove();
390	        refreshNumbers();
391	      }
392	    }
393	  });
394	  document.getElementById('add-spec').addEventListener('click', addSpec);
395	
396	  function clearErrors() {
397	    statusBox.className = '';
398	    statusBox.textContent = '';
399	    var slots = form.querySelectorAll('.err');
400	    for (var i = 0; i < slots.length; i++) slots[i].textContent = '';
401	    var invalids = form.querySelectorAll('.invalid');
402	    for (var j = 0; j < invalids.length; j++) invalids[j].classList.remove('invalid');
403	  }
404	  function setSlotError(container, key, text, inputKey) {
405	    var slot = container.querySelector('[data-err="' + key + '"]');
406	    if (slot) slot.textContent = text;
407	    if (inputKey) {
408	      var input = container.querySelector('[' + inputKey + ']');
409	      if (input) input.classList.add('invalid');
410	    }
411	  }
412	  function showFailure(message, details) {
413	    statusBox.className = 'error';
414	    statusBox.textContent = message + '（已保留填写内容，修正后可再次提交）';
415	    if (!details) return;
416	    details.forEach(function (detail) {
417	      if (detail.field === 'name') {
418	        setSlotError(form, 'name', detail.message, 'data-name-input');
419	        return;
420	      }
421	      var cards = specsBox.querySelectorAll('[data-spec]');
422	      var card = cards[detail.specIndex];
423	      if (!card) return;
424	      if (detail.field === 'attrName' || detail.field === 'attrValue') {
425	        var rows = card.querySelectorAll('.attr-row');
426	        var row = rows[detail.attributeIndex];
427	        if (row) {
428	          var key = detail.field === 'attrName' ? 'attrName' : 'attrValue';
429	          var inputKey = detail.field === 'attrName' ? 'data-attr-name' : 'data-attr-value';
430	          setSlotError(row, key, detail.message, inputKey);
431	        }
432	        return;
433	      }
434	      var inputKey = detail.field === 'price' ? 'data-price' : detail.field === 'stock' ? 'data-stock' : null;
435	      setSlotError(card, detail.field, detail.message, inputKey);
436	    });
437	  }
438	  function showSaveError() {
439	    statusBox.className = 'error';
440	    statusBox.textContent = '保存失败，商品未保存，请稍后重试。已有商品没有受到影响，填写内容仍然保留。';
441	  }
442	
443	  function collectPayload() {
444	    var payload = { name: nameInput.value, specs: [] };
445	    var cards = specsBox.querySelectorAll('[data-spec]');
446	    for (var i = 0; i < cards.length; i++) {
447	      var card = cards[i];
448	      var attributes = [];
449	      var rows = card.querySelectorAll('.attr-row');
450	      for (var j = 0; j < rows.length; j++) {
451	        attributes.push({
452	          name: rows[j].querySelector('[data-attr-name]').value,
453	          value: rows[j].querySelector('[data-attr-value]').value
454	        });
455	      }
456	      var stockRaw = card.querySelector('[data-stock]').value;
457	      var stock;
458	      if (stockRaw === '') {
459	        stock = null;
460	      } else if (/^\\d+$/.test(stockRaw) && Number(stockRaw) <= Number.MAX_SAFE_INTEGER) {
461	        stock = Number(stockRaw);
462	      } else {
463	        stock = stockRaw;
464	      }
465	      payload.specs.push({
466	        attributes: attributes,
467	        price: card.querySelector('[data-price]').value,
468	        stock: stock
469	      });
470	    }
471	    return payload;
472	  }
473	
474	  addSpec();
475	  form.addEventListener('submit', function (event) {
476	    event.preventDefault();
477	    clearErrors();
478	    submitBtn.disabled = true;
479	    fetch('/api/products', {
480	      method: 'POST',
481	      headers: { 'content-type': 'application/json' },
482	      body: JSON.stringify(collectPayload())
483	    }).then(function (response) {
484	      return response.json().catch(function () { return null; }).then(function (data) {
485	        return { status: response.status, data: data };
486	      });
487	    }).then(function (result) {
488	      submitBtn.disabled = false;
489	      if (result.status === 201 && result.data) {
490	        window.location.assign('/');
491	        return;
492	      }
493	      if (result.status === 400 && result.data) {
494	        showFailure(result.data.error || '提交内容不符合要求', result.data.details);
495	      } else {
496	        showSaveError();
497	      }
498	    }).catch(function () {
499	      submitBtn.disabled = false;
500	      showSaveError();
501	    });
502	  });
503	})();
504	`;
505	
506	function renderPage(products: Product[]): string {
507	  return `<!doctype html>
508	<html lang="zh-CN">
509	<head>
510	<meta charset="utf-8">
511	<meta name="viewport" content="width=device-width,initial-scale=1">
512	<title>Cartwell · 商品目录与购物订单</title>
513	<style>${PAGE_STYLE}</style>
514	</head>
515	<body>
516	<main>
517	<h1>Cartwell</h1>
518	<p>商品目录与购物订单</p>
519	<section>
520	<h2>商品列表</h2>
521	${renderProductList(products)}
522	</section>
523	<section>
