525	<form id="product-form" novalidate>
526	<p class="field"><label>商品名称 <input type="text" id="product-name" data-name-input maxlength="200" placeholder="输入商品名称"></label>
527	<span class="err" data-err="name"></span></p>
528	<div id="specs"></div>
529	<p><button type="button" id="add-spec">添加规格</button></p>
530	<div id="form-status" role="alert"></div>
531	<div class="form-actions"><button type="submit" class="primary" id="submit-btn">提交商品</button></div>
532	</form>
533	</section>
534	<p><a href="/api/products">查看商品列表接口</a> · <a href="/health">服务状态</a></p>
535	</main>
536	<script>${PAGE_SCRIPT}</script>
537	</body>
538	</html>`;
539	}
540	
541	const ERROR_PAGE = (message: string): string => `<!doctype html>
542	<html lang="zh-CN"><meta charset="utf-8"><title>Cartwell · 出错了</title>
543	<body style="font-family:system-ui,sans-serif;max-width:40rem;margin:3rem auto;padding:0 1rem">
544	<h1>暂时无法读取商品</h1><p>${escapeHtml(message)}</p><p><a href="/">返回首页重试</a></p></body></html>`;
545	
546	// ---------- HTTP 服务 ----------
547	
548	function respond(res: ServerResponse, status: number, value: unknown, html = false, allow?: string): void {
549	  if (res.destroyed || res.writableEnded) return; // 客户端可能已在读取请求体期间断开
550	  const body = html ? String(value) : JSON.stringify(value);
551	  const headers: Record<string, string> = {
552	    'content-type': html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
553	    'content-length': String(Buffer.byteLength(body)),
554	  };
555	  if (status === 405 && allow) headers.allow = allow;
556	  res.writeHead(status, headers);
557	  res.end(body);
558	}
559	
560	function readJsonBody(req: IncomingMessage): Promise<unknown> {
561	  return new Promise((resolve, reject) => {
562	    let size = 0;
563	    const chunks: Buffer[] = [];
564	    let bodyTooLarge = false;
565	    let settled = false;
566	    const fail = (reason: 'too-large' | 'invalid-json'): void => {
567	      if (settled) return;
568	      settled = true;
569	      reject(new Error(reason));
570	    };
571	    req.on('data', (chunk: Buffer) => {
572	      size += chunk.length;
573	      if (bodyTooLarge) return; // 已确认超限，继续排空后续数据即可
574	      // 超限只标记、停止缓存，绝不销毁连接：未读完的请求数据会导致随后写出的响应被
575	      // TCP RST，客户端只能看到连接重置。继续读完整个请求体后再在 'end' 中拒绝。
576	      if (size > MAX_BODY_BYTES) {
577	        bodyTooLarge = true;
578	        chunks.length = 0;
579	        return;
580	      }
581	      chunks.push(chunk);
582	    });
583	    req.on('end', () => {
584	      if (bodyTooLarge) {
585	        fail('too-large');
586	        return;
587	      }
588	      try {
589	        resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')));
590	      } catch {
591	        fail('invalid-json');
592	      }
593	    });
594	    req.on('error', () => fail(bodyTooLarge ? 'too-large' : 'invalid-json'));
595	  });
596	}
597	
598	const ALLOWED_METHODS: Record<string, string[]> = {
599	  '/': ['GET'],
600	  '/health': ['GET'],
601	  '/api/products': ['GET', 'POST'],
602	};
603	
604	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
605	  let route: string;
606	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
607	
608	  const allowed = ALLOWED_METHODS[route];
609	  if (!allowed) { respond(res, 404, { error: 'not found' }); return; }
610	  const method = req.method ?? '';
611	  if (!allowed.includes(method)) {
612	    respond(res, 405, { error: 'method not allowed', allowed }, false, allowed.join(', '));
613	    return;
614	  }
615	
616	  if (route === '/health') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
617	
618	  if (route === '/' && method === 'GET') {
619	    try {
620	      respond(res, 200, renderPage(readProducts()), true);
621	    } catch {
622	      respond(res, 500, ERROR_PAGE('商品数据暂时无法读取，已有记录未被修改。'), true);
623	    }
624	    return;
625	  }
626	
627	  if (route === '/api/products' && method === 'GET') {
628	    try {
629	      respond(res, 200, { [RESOURCE]: readProducts() });
630	    } catch {
631	      respond(res, 500, { error: 'unable to read products' });
632	    }
633	    return;
634	  }
635	
636	  // POST /api/products
637	  readJsonBody(req).then((input) => {
638	    const result = validateProduct(input);
639	    if (!result.ok) {
640	      respond(res, 400, { error: '商品校验未通过，未创建任何记录', details: result.errors });
641	      return;
642	    }
643	    const product: Product = {
644	      id: randomUUID(),
645	      name: result.name,
646	      specs: result.specs,
647	      createdAt: new Date().toISOString(),
648	    };
649	    try {
650	      const products = readProducts();
651	      products.unshift(product); // 新创建的商品排在最前
652	      saveProducts(products);
653	    } catch {
654	      respond(res, 500, { error: '商品保存失败，请稍后重试；已有商品未受影响' });
655	      return;
656	    }
657	    respond(res, 201, product);
658	  }).catch((error: Error) => {
659	    if (error.message === 'too-large') {
660	      respond(res, 400, {
661	        error: `请求体超过 ${MAX_BODY_BYTES} 字节的大小限制，商品没有保存`,
662	        limitBytes: MAX_BODY_BYTES,
663	      });
664	    } else {
665	      respond(res, 400, { error: '请求内容不是合法的 JSON' });
666	    }
667	  });
668	});
669	
670	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
671	server.listen(port, host, (): void => {
672	  const address = server.address();
673	  if (address && typeof address !== 'string') {
674	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
675	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
676	  }
677	});
678	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
679	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
680	}
