1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { spawn, spawnSync, type ChildProcess } from 'node:child_process';
4	import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
5	import { tmpdir } from 'node:os';
6	import { join } from 'node:path';
7	import { once } from 'node:events';
8	import net from 'node:net';
9	
10	// 回归测试：通过真实的 HTTP 请求、响应和保存后的商品列表观察新增商品行为，
11	// 重点保证同一商品内重复规格的判定不随属性填写顺序变化。
12	
13	const SERVER_PATH = join(import.meta.dirname, 'server.ts');
14	
15	interface RunningServer {
16	  url: string;
17	  dataDir: string;
18	  child: ChildProcess;
19	}
20	
21	function startServer(): Promise<RunningServer> {
22	  const dataDir = mkdtempSync(join(tmpdir(), 'cartwell-test-'));
23	  const child = spawn(
24	    process.execPath,
25	    [SERVER_PATH, 'serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
26	    { stdio: ['ignore', 'pipe', 'pipe'] },
27	  );
28	  return new Promise((resolve, reject) => {
29	    let buffer = '';
30	    let settled = false;
31	    const fail = (error: Error): void => {
32	      if (!settled) { settled = true; reject(error); }
33	    };
34	    child.stdout!.setEncoding('utf8');
35	    child.stdout!.on('data', (chunk: string) => {
36	      buffer += chunk;
37	      const match = buffer.match(/listening on (http:\/\/\S+)/);
38	      if (match && !settled) {
39	        settled = true;
40	        resolve({ url: match[1], dataDir, child });
41	      }
42	    });
43	    child.stderr!.setEncoding('utf8');
44	    child.stderr!.on('data', (chunk: string) => { buffer += chunk; });
45	    child.once('error', () => fail(new Error('无法启动服务进程')));
46	    child.once('exit', (code) => fail(new Error(`服务提前退出，退出码 ${code}：${buffer}`)));
47	  });
48	}
49	
50	async function stopServer(server: RunningServer): Promise<void> {
51	  server.child.kill('SIGTERM');
52	  await Promise.race([
53	    once(server.child, 'exit'),
54	    new Promise((resolve) => setTimeout(resolve, 5000)),
55	  ]);
56	  if (server.child.exitCode === null) server.child.kill('SIGKILL');
57	  rmSync(server.dataDir, { recursive: true, force: true });
58	}
59	
60	interface ApiResult {
61	  status: number;
62	  body: any;
63	}
64	
65	async function postProduct(url: string, payload: unknown): Promise<ApiResult> {
66	  const response = await fetch(`${url}/api/products`, {
67	    method: 'POST',
68	    headers: { 'content-type': 'application/json' },
69	    body: JSON.stringify(payload),
70	  });
71	  return { status: response.status, body: await response.json() };
72	}
73	
74	async function getProducts(url: string): Promise<any[]> {
75	  const response = await fetch(`${url}/api/products`);
76	  assert.equal(response.status, 200);
77	  const body = await response.json();
78	  assert.ok(Array.isArray(body.products));
79	  return body.products;
80	}
81	
82	const MAX_BODY_BYTES = 1_048_576;
83	
84	interface RawResponse {
85	  statusLine: string;
86	  statusCode: number;
87	  headers: string;
88	  body: Buffer;
89	  hadError: boolean;
90	}
91	
92	// 直接用 TCP 发送原始 HTTP 请求，便于精确控制 Content-Length、分块边界和发送节奏，
93	// 同时观察连接是否被重置以及响应是否完整（fetch 无法区分「连接断开」与「400 响应」）。
94	function rawRequest(url: string, headExtra: string, chunks: Buffer[]): Promise<RawResponse> {
95	  const { port } = new URL(url);
96	  return new Promise((resolve, reject) => {
97	    const client = net.connect(Number(port), '127.0.0.1');
